import React, { useState, useRef, useEffect } from 'react';

const ImagePositionSelector = ({ imageUrl, initialPosition, onChange }) => {
  const containerRef = useRef(null);
  const [position, setPosition] = useState({ x: 50, y: 50 });
  const [isDragging, setIsDragging] = useState(false);
  const dragStartRef = useRef(null);
  const positionRef = useRef(position);

  // Keep the position ref updated with the latest state
  useEffect(() => {
    positionRef.current = position;
  }, [position]);

  // Parse initial position into x, y percentages
  useEffect(() => {
    if (initialPosition) {
      // Handle both string format "x% y%" and named positions
      if (initialPosition.includes('%')) {
        const parts = initialPosition.split(' ');
        if (parts.length === 2) {
          const x = parseInt(parts[0], 10);
          const y = parseInt(parts[1], 10);
          if (!isNaN(x) && !isNaN(y)) {
            setPosition({ x, y });
          }
        }
      } else {
        const positionMap = {
          'center': { x: 50, y: 50 },
          'top': { x: 50, y: 0 },
          'bottom': { x: 50, y: 100 },
          'left': { x: 0, y: 50 },
          'right': { x: 100, y: 50 },
          'top left': { x: 0, y: 0 },
          'top right': { x: 100, y: 0 },
          'bottom left': { x: 0, y: 100 },
          'bottom right': { x: 100, y: 100 }
        };
        
        setPosition(positionMap[initialPosition] || { x: 50, y: 50 });
      }
    }
  }, [initialPosition]);

  // Convert position to CSS background-position and notify parent
  useEffect(() => {
    const backgroundPosition = `${position.x}% ${position.y}%`;
    onChange(backgroundPosition);
  }, [position, onChange]);

  // Set up mouse event handlers
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const handleMouseDown = (e) => {
      e.preventDefault();
      setIsDragging(true);
      
      const rect = container.getBoundingClientRect();
      const x = ((e.clientX - rect.left) / rect.width) * 100;
      const y = ((e.clientY - rect.top) / rect.height) * 100;
      
      dragStartRef.current = { x, y };
      setPosition({ 
        x: Math.max(0, Math.min(100, x)), 
        y: Math.max(0, Math.min(100, y)) 
      });
    };

    const handleMouseMove = (e) => {
      if (!isDragging) return;
      e.preventDefault();
      
      const rect = container.getBoundingClientRect();
      const x = ((e.clientX - rect.left) / rect.width) * 100;
      const y = ((e.clientY - rect.top) / rect.height) * 100;
      
      setPosition({ 
        x: Math.max(0, Math.min(100, x)), 
        y: Math.max(0, Math.min(100, y)) 
      });
    };

    const handleMouseUp = () => {
      setIsDragging(false);
      dragStartRef.current = null;
    };

    // Add event listeners
    container.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    window.addEventListener('mouseleave', handleMouseUp);

    // Clean up
    return () => {
      container.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('mouseleave', handleMouseUp);
    };
  }, [isDragging]);

  // Set up touch event handlers
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const handleTouchStart = (e) => {
      if (e.touches.length !== 1) return;
      e.preventDefault();
      setIsDragging(true);
      
      const touch = e.touches[0];
      const rect = container.getBoundingClientRect();
      const x = ((touch.clientX - rect.left) / rect.width) * 100;
      const y = ((touch.clientY - rect.top) / rect.height) * 100;
      
      dragStartRef.current = { x, y };
      setPosition({ 
        x: Math.max(0, Math.min(100, x)), 
        y: Math.max(0, Math.min(100, y)) 
      });
    };

    const handleTouchMove = (e) => {
      if (!isDragging || e.touches.length !== 1) return;
      e.preventDefault();
      
      const touch = e.touches[0];
      const rect = container.getBoundingClientRect();
      const x = ((touch.clientX - rect.left) / rect.width) * 100;
      const y = ((touch.clientY - rect.top) / rect.height) * 100;
      
      setPosition({ 
        x: Math.max(0, Math.min(100, x)), 
        y: Math.max(0, Math.min(100, y)) 
      });
    };

    const handleTouchEnd = () => {
      setIsDragging(false);
      dragStartRef.current = null;
    };

    // Add event listeners
    container.addEventListener('touchstart', handleTouchStart, { passive: false });
    window.addEventListener('touchmove', handleTouchMove, { passive: false });
    window.addEventListener('touchend', handleTouchEnd);
    window.addEventListener('touchcancel', handleTouchEnd);

    // Clean up
    return () => {
      container.removeEventListener('touchstart', handleTouchStart);
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
      window.removeEventListener('touchcancel', handleTouchEnd);
    };
  }, [isDragging]);

  // Preset position buttons
  const presetPositions = [
    { name: 'Center', x: 50, y: 50 },
    { name: 'Top', x: 50, y: 0 },
    { name: 'Bottom', x: 50, y: 100 },
    { name: 'Left', x: 0, y: 50 },
    { name: 'Right', x: 100, y: 50 }
  ];

  const handlePresetClick = (preset) => {
    setPosition({ x: preset.x, y: preset.y });
  };

  return (
    <div className="image-position-selector">
      <div className="position-preview-container">
        <div 
          ref={containerRef}
          className="position-preview"
          style={{
            backgroundImage: `url(${imageUrl})`,
            backgroundPosition: `${position.x}% ${position.y}%`,
            backgroundSize: 'cover',
            cursor: isDragging ? 'grabbing' : 'grab'
          }}
        >
          <div 
            className="position-indicator"
            style={{
              left: `${position.x}%`,
              top: `${position.y}%`
            }}
          ></div>
          <div className="position-instructions">
            Click and drag to adjust image position
          </div>
        </div>
      </div>
      <div className="position-controls">
        <div className="position-presets">
          {presetPositions.map(preset => (
            <button 
              key={preset.name}
              type="button" 
              className="position-preset"
              onClick={() => handlePresetClick(preset)}
            >
              {preset.name}
            </button>
          ))}
        </div>
        <div className="position-values">
          X: {Math.round(position.x)}%, Y: {Math.round(position.y)}%
        </div>
      </div>
    </div>
  );
};

export default ImagePositionSelector;
